#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> bills(n);
    for (int i = 0; i < n; i++) cin >> bills[i];

    long long fives = 0, tens = 0;
    bool ok = true;
    for (long long bill : bills) {
        if (bill == 5) {
            fives++;
        } else if (bill == 10) {
            if (fives == 0) { ok = false; break; }
            fives--;
            tens++;
        } else {
            if (tens > 0 && fives > 0) { tens--; fives--; }
            else if (fives >= 3) fives -= 3;
            else { ok = false; break; }
        }
    }
    cout << (ok ? "yes" : "no") << "\n";

    return 0;
}

